// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MultiplicatorX3 c;

    // Test contract is msg.sender at deploy time, hence becomes Owner; it must accept Ether.
    receive() external payable {}

    function setUp() public { c = new MultiplicatorX3(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the contract directly so it has a positive balance to withdraw
        vm.deal(address(c), amount);
        assertEq(address(c).balance, amount);

        // owner (this test contract) calls withdraw with some attached value
        vm.deal(address(this), amount);
        vm.prank(address(this));
        c.withdraw{value: amount}();

        // Rule: a successful withdraw() by the Owner drains the ENTIRE balance of c to the Owner.
        assertTrue(address(c).balance == 0);
    }
}
